def build():
    rng = random.Random(20261109)
    disciplines = [{'id': key, 'name': name, 'description': description, 'teacher': teacher, 'semester': 3} for key, name, description, teacher in DISCIPLINES]
    common = ['machine_learning', 'python', 'databases', 'web', 'algorithms', 'statistics']
    groups = [
        {'id': 'pi_21', 'name': 'ПИ-21', 'program': 'Программная инженерия', 'year': 2, 'discipline_ids': common + ['software', 'security']},
        {'id': 'ivt_21', 'name': 'ИВТ-21', 'program': 'Информатика и вычислительная техника', 'year': 2, 'discipline_ids': common + ['networks', 'os']},
    ]
    extra_materials, extra_quizzes = [], {}
    for discipline_id, topics in TOPICS.items():
        for number, (title, questions) in enumerate(topics, 1):
            material_id = f'{discipline_id}_{number:02d}'
            prepared_questions = []
            for index, (text, options, explanation) in enumerate(questions):
                correct = (index + number) % 3
                rotated = options[-correct:] + options[:-correct] if correct else options
                prepared_questions.append({'id': f'{material_id}_q{index + 1}', 'text': text, 'options': rotated, 'correct': correct, 'explanation': explanation})
            extra_materials.append({'id': material_id, 'discipline_id': discipline_id, 'title': title, 'topic': title, 'level': 'начальный',
                                    'summary': questions[0][2], 'outcomes': [question[0].rstrip('?') for question in questions[:3]],
                                    'content': f'{title}. В этом разделе рассматриваются основные понятия и их применение.\n\n' + '\n\n'.join(question[2] for question in questions)})
            extra_quizzes[material_id] = {'practice': f'По теме «{title}» приведите собственный пример и объясните ответ на каждый вопрос теста. Затем повторите проверку.', 'questions': prepared_questions}
    original_quizzes = json.loads((ROOT / 'knowledge-project/quizzes.json').read_text(encoding='utf-8'))
    all_quizzes = {**original_quizzes, **extra_quizzes}
    course_materials = {'machine_learning': ['mat_01', 'mat_02', 'mat_03', 'mat_04']}
    for material in extra_materials:
        course_materials.setdefault(material['discipline_id'], []).append(material['id'])
    surnames = ['Андреев', 'Белов', 'Васильев', 'Громов', 'Денисов', 'Егоров', 'Жуков', 'Зайцев', 'Ильин', 'Крылов', 'Лебедев', 'Макаров', 'Никитин', 'Орлов', 'Петров']
    female_surnames = ['Алексеева', 'Беляева', 'Волкова', 'Гусева', 'Данилова', 'Ершова', 'Жданова', 'Зимина', 'Иванова', 'Кузнецова', 'Лукина', 'Морозова', 'Новикова', 'Осипова', 'Павлова']
    students, activities = [], []
    for group_index, group in enumerate(groups):
        for index in range(15):
            student_id = f'demo_{group["id"]}_{index + 1:03d}'
            name = f'{surnames[index]} {("Алексей", "Иван", "Михаил", "Дмитрий", "Артём")[index % 5]} {("Сергеевич", "Андреевич", "Игоревич")[index % 3]}' if group_index == 0 else f'{female_surnames[index]} {("Анна", "Мария", "Елена", "Дарья", "Полина")[index % 5]} {("Александровна", "Сергеевна", "Игоревна")[index % 3]}'
            profile = ('advanced', 'steady', 'practice', 'support', 'new')[index % 5]
            students.append({'id': student_id, 'full_name': name, 'group_id': group['id'], 'active': True, 'source': 'synthetic', 'scenario': profile})
            sequence = 0
            for course_id in group['discipline_ids']:
                for material_id in course_materials[course_id]:
                    if profile == 'new' or rng.random() > {'advanced': 1, 'steady': .8, 'practice': .7, 'support': .65}[profile]:
                        continue
                    scores = [rng.choice([80, 100])] if profile == 'advanced' else [rng.choice([40, 60]), rng.choice([80, 100])] if profile == 'steady' else [rng.choice([40, 60, 80])] if profile == 'practice' else [rng.choice([20, 40])]
                    for score in scores:
                        questions = all_quizzes[material_id]['questions']
                        answers = [question['correct'] if number < score // 20 else (question['correct'] + 1) % len(question['options']) for number, question in enumerate(questions)]
                        stamp = datetime(2026, 11, 1, 8) + timedelta(days=index % 7, minutes=sequence * 13 + group_index * 3)
                        activities.append({'student_id': student_id, 'material_id': material_id, 'answers': answers, 'score': score, 'created_at': stamp.strftime('%Y-%m-%d %H:%M:%S')})
                        sequence += 1
    data = {'version': 'academy-demo-v1', 'synthetic': True, 'description': 'Полностью вымышленные студенты, учебные планы и результаты для проверки интерфейса. Не данные OULAD.',
            'groups': groups, 'disciplines': disciplines, 'students': students, 'activities': activities}
    for name, value in [('academy.json', data), ('additional_materials.json', extra_materials), ('additional_quizzes.json', extra_quizzes)]:
        (OUTPUT / name).write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding='utf-8')
    for name, rows, columns in [('students.csv', students, ['id', 'full_name', 'group_id', 'active', 'source', 'scenario']),
                                ('disciplines.csv', disciplines, ['id', 'name', 'description', 'teacher', 'semester']),
                                ('activities.csv', activities, ['student_id', 'material_id', 'score', 'created_at'])]:
        with (OUTPUT / name).open('w', encoding='utf-8-sig', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=columns, extrasaction='ignore', delimiter=';')
            writer.writeheader()
            writer.writerows(rows)
    with (OUTPUT / 'group_disciplines.csv').open('w', encoding='utf-8-sig', newline='') as stream:
        writer = csv.writer(stream, delimiter=';')
        writer.writerow(['group_id', 'group_name', 'discipline_id'])
        for group in groups:
            writer.writerows((group['id'], group['name'], course) for course in group['discipline_ids'])
    print(json.dumps({'groups': len(groups), 'students': len(students), 'disciplines': len(disciplines), 'materials': len(all_quizzes), 'questions': sum(len(quiz['questions']) for quiz in all_quizzes.values()), 'attempts': len(activities)}))
    # Reapply the authored course texts after regenerating synthetic catalogs.
    from build_lessons import build as build_lessons
    build_lessons()


if __name__ == '__main__':
    build()
